            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(g):
    g=[row[:] for row in g]; h=len(g); w=len(g[0])
    bg=Counter(sum(g,[])).most_common(1)[0][0]
    # multi-cell comps = objects; single-cell comps = seeds. Mixed-color comps still objects here.
    def comps_():
        seen=[[False]*w for _ in range(h)]; out=[]
        for i in range(h):
            for j in range(w):
                if g[i][j]!=bg and not seen[i][j]:
                    q=deque([(i,j)]); seen[i][j]=True; cells=[]
                    while q:
                        x,y=q.popleft(); cells.append((x,y))
                        for dx in(-1,0,1):
                            for dy in(-1,0,1):
                                p,r=x+dx,y+dy
                                if 0<=p<h and 0<=r<w and not seen[p][r] and g[p][r]!=bg:
                                    seen[p][r]=True; q.append((p,r))
                    out.append(cells)
        return out
    cs=comps_()
    objs=[c for c in cs if len(c)>1]; seeds=[c[0] for c in cs if len(c)==1]
    # map each object to a canonical template: set of (dr,dc) relative to topleft, colors preserved?
    # Try: object T at topleft (tr,tc) with cells {(r,c):col}. Template rel = {(r-tr, c-tc): col}
    info=[]
    for c in objs:
        tr=min(x for x,y in c); tc=min(y for x,y in c)
        tmpl={(r-tr,cc-tc):g[r][cc] for (r,cc) in c}
        info.append((tr,tc,tmpl))
    out=[row[:] for row in g]
    for s in seeds:
        sr,sc=s; scolor=g[sr][sc]
        # nearest object (by chebyshev distance from seed to object cells)
        best=None;bd=10**9
        for tr,tc,tmpl in info:
            dmin=min(max(abs(sr-r),abs(sc-c)) for (r,c) in [(r,c) for r,c in tmpl]) if tmpl else 10**9
            # distance from seed to nearest cell of object
            dmin=min(max(abs(sr-r_),abs(sc-c_)) for (r_,c_) in c)
            if dmin<bd: bd=dmin;bi=(tr,tc,tmpl)
        tr,tc,tmpl=bi
        # target anchor: seed takes role of the template cell closest to seed position within object frame
        # i.e. we want template placed at (a,b) such that some template cell (dr,dc) lands on (sr,sc)
        # choose placement minimizing distance between object and seed after placement (object moved so it's adjacent)
        cand=[]
        for (dr,dc) in tmpl:
            a=sr-dr; b=sc-dc
            # overlap check: moved cells must not overlap other objects/seeds except own? allow overlapping?
            occ=lambda aa,bb_:(out[aa][bb_] not in (bg,) and (aa,bb_) not in [ (x,y) for x,y in seeds]+[(s[0],s[1])])
            cells_ok=True
            for (rr,ccc) in tmpl.values():
                rr_=a+rr; cc_=b+ccc
                v=out[rr_][cc_]
                if v!=bg and v!=scolor and (rr_,cc_)!=s:
                    cells_ok=False; break
            if cells_ok:
                cand.append((max(abs(sr-(a+dr)),abs(sc-(b+dc))),a,b))
        cand.sort()
        da,db=cand[0][1],cand[0][2]
        for (dr,dc),v in tmpl.items():
            out[da+dr][db+dc]=scolor
    return out

